function [o] = cm_offset(cpa, dir)
%CM_OFFSET  The offset [m] (body): cpa [m] along the direction dir (unnormalised), cpa dir/|dir|.
%   cpa: real[m] (passed in m)
%   dir: real[1][3] (passed a plain number)
%   returns o: real[m][3] (passed in m)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    o = zeros(3, 1);
    n = asils.pc.sqrt_((((dir(1) * dir(1)) + (dir(2) * dir(2))) + (dir(3) * dir(3))));
    o = [((cpa * dir(1)) / n); ((cpa * dir(2)) / n); ((cpa * dir(3)) / n)];
end
